) AS (
  VALUES 
    (231::BIGINT, 'El profe explica bastante bien, pero deja bastantes cosas al aire libre. En mi caso nunca explicó bien como rellenar el cajetin. Las prácticas que deja son "sencillas".'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'c41be12bbc1869cdb65148ebc8c41d6ad2f473fec709c631307123cbc9e9435c'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es buena nota. Explica bastante claro, pero deja por fuera varias cosas. Califica justamente (ni más, ni menos) y OJO con las prácticas supervisadas, la mayoría fueron duras y da poco tiempo. Dura demasiado revisando las evaluaciones, entonces usted no sabe como va hasta final de semestre. VALORE UD'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2026-07-08T00:00:00+00:00'::TIMESTAMPTZ, '89de29fc27bd09344a884f87965ec11fb129a9853c391b0f4404a482d3e22834'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'De las mejores opciones para dibujo. Califica justo, sin embargo es demasiado desorganizado. Se espera hasta el último momento para subir notas. Si matricula con él, procure esforzarse ya que sí hace la diferencia si ve que uno le pone.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'a93703be485784cf4328a7a48e77b626039ac7a0753ccf58c2f8ab976031754e'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Siempre pasa lista, nunca hace clases virtuales, Recomendación: Aprenda acotar bien, es muy estricto con eso.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, '6f19379958404f3c9fd9a79b82d82511cedc78be2fa354150975e077276fa8cc'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'La mejor opción para matricular DT, es súper amable para atender dudas, califica justo y las prácticas que hace en clase son de bastante ayuda. Aunque no sube las calificaciones hasta el final de semestre si deja las soluciones de las tareas antes de cada examen para tener idea de como va uno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '936c1c0027f25fc40c8ba3f2a886b976f565050eb64a55b0af0699f5d5a079db'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'La clase entretenida, el profe le ayuda a uno si le ve que le pone, pero sus expliaciones no son muy claras y tarda bastante en calificar'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'cfb0342ac4b59278a23569446c28939d6bfa8bb800ec55a0d694602f9a44a4bf'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'Un curso interesante en materia de seguridad laboral, el curso no se basa unicamente en circuitos, por lo contrario, el procesor da las bases y espera que los estudiantes apliquen conocimientos de seguridad. Puede ser un poco lerdo en revisar notas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2024-12-11T00:00:00+00:00'::TIMESTAMPTZ, '226051ec7b8a14e5d0717c0d78d1bb33bff4769150d44b7c286f42475efc0a03'::TEXT, ARRAY[1445]::BIGINT[]),
    (231::BIGINT, 'Es demasiado buen profe explica con mucha claridad y si no entiende algo es está siempre disponible para ayudarlo La materia es difícil si nunca a tenido conocimiento previo de AutoCAD pero siempre se esfuerza para que uno lo entienda de mejor manera'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-09-27T00:00:00+00:00'::TIMESTAMPTZ, '15c0b5be6c47820c78b086219bf0c422e2f88ad92c0e57589586ca0aea1ac1b0'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'Muy buen profe da mucha risa jaja matriculen con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '5005438e6e92f3351970bb77bebe8c005c1333aa75f26df54bae1abbd3f20faf'::TEXT, ARRAY[3088]::BIGINT[]),
    (231::BIGINT, 'Es buen profe y lo que fue mi clase la mayoría pasó, no obstante, primero dura demasiado en calificar (literal entregó todo el día de la entrega de actas) y segundo a veces no ayuda y o una de dos, te deja en visto o dice comentarios como "no está bien pero tampoco está mal" y llega a ser frustrante'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a22198a0cfc12898f3fae0567245793d0d6b7c987cb1a248712f8b1dfe631e3f'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'Es muy flexible e intenta conectar con el estudiante. Matricule con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-07T00:00:00+00:00'::TIMESTAMPTZ, '6b144f2e75a341f9e237ba00d92999f5e36d8fabf0b22aa372b94ba6fe746432'::TEXT, ARRAY[3088]::BIGINT[]),
    (231::BIGINT, 'El profe deja muchas maquetas y proyectos grandes, así que hay que ponerle y estar preparado para todo porque le gusta hacer "experimentos". Si ayuda bastante y es consciente de que deja cosas muy pesadas, entonces es flexible.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '087ca8a6d5bbb7578eb2da36f699bfa69681f256928adb2b1c50fa94b72c86af'::TEXT, ARRAY[3088]::BIGINT[]),
    (231::BIGINT, 'El profe ayuda bastante y usted puede ir a hacer las tareas en hora de consulta a la par de él si usted lo necesita. Explica bien y es buena gente, el curso disfruta y no lo hace tan pesado. Lo único malo es que da las calificaciones hasta el puro final del semestre, pero casi nadie se queda.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-07-10T00:00:00+00:00'::TIMESTAMPTZ, '3d9e16926a5634abd5597540450ab3ba7ad2c5abaca814cb21a60129281a19cd'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'Este profe es muy crack, de lo mejor que me ha tocado en el tec.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-06-28T00:00:00+00:00'::TIMESTAMPTZ, '2cd344a3f9b96a994b8e388564cd2319ac4a970a1382cb41c6c2999f0e211c5d'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'Es buen profe, un poco vago. Da todas las notas hasta el final, por ende hay incertidumble de como va el curso. Sin embargo las clases son buenas, explica bien y ayuda.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd58c518db8276e626c2b400142f5cc40c1404f79549b4b3892050e21ea615fbf'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'él es muy desordenado entonces te va dar las notas de cualquier trabajo días antes de que se haga la entrega de actas, ya que es muy desordenado. Cuesta un poco que te ayude al entender a veces y su forma de explicar no es clara.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '7792e12144b4cf4274f841267c78897bb0e204ce250aad4b0990e65a13a827ac'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'No es mal profe, explica muy bien todo pero es muy muy desordenado, usted no recibe ni una sola retroaliementación hasta el puro limite de entrega de actas, no califica absolutamente nada, uno no puede saber como va y si está haciendo las cosas bien y no le tiene lástima en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a4afee7171b010a711c2fa0afb48bff455b38a1bdf962ac2eafb90178264a3a3'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'Buen profe, explica bien, tarda en dar notas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '28d6773e18a8278c92938cdf06acdd8f1ff15593e0455ef1e305bfc0d7063df9'::TEXT, ARRAY[1428]::BIGINT[]),
    (231::BIGINT, 'EXCELENTE PROFESOR, SIN NINGUNA DUDA MATRICULE CON Él, ES UN GRAN PROFESIONAL LE ENTENDÍ TODO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-10T00:00:00+00:00'::TIMESTAMPTZ, '8bfa63efacdcde1605d3d1f49af9d2a4edfad0622ff66f671bdfa09954161c7c'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Explica muy bien. Da clases muy completas. Ayuda bastante en las horas de consulta. Es comprensible con el tiempo de entregar las tareas y demás evaluaciones. El problema que tiene es que da las calificaciones hasta el final, por tanto no hay retroalimentación.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, '12cc0c7b1a8d11cdcba57d7c6341dcfff4979b3b4b2998a17cd155e9126a689f'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Explica demasiado bien y las clases son muy completas. Es bastante relajado por lo que deja bastante tiempo para entregar las tareas y además revisa suave. El problema es que no entrega calificaciones hasta el final del semestre, por lo que realmente no hay retroalimentación.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'e6bf97844422e89c23b97adc4cec8caf941988009bc8ca8ce0553d97934819c7'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Explica bastante bien las clases y en general en un muy buen profe. Sin embargo, dio las evaluaciones casi que al final de semestre.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'd4d40fb738b7e6d3255eb66abf825ee585dd2412a4d9471e73fe08100ef5a85a'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Buen profe, explica bien, con detalle y orden, solo este espabilado a lo que el esta diciendo, usa varias herramientas que ayudan bastante el entendimiento, resuelve bastantes problemas y tambien da recomendaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-21T00:00:00+00:00'::TIMESTAMPTZ, '6cce89db390a0cd94e2b6b4fb91d34120640f6ed714b703ecc245c798eba9d9d'::TEXT, ARRAY[1726]::BIGINT[]),
    (231::BIGINT, 'el profesor es muy buena persona. pero con la virtualidad las tareas son realmente cansadas y en mi caso fue una persona realmente irresponsable con las evaluaciones y desordenado con los trabajos que hay que hacer, si quiere pasar meta con el pero aténgase a que recibirá todo al final'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'e8b6bbe6dd024dce93e3faaa4f783d7d629ce724d5345e891dd8df293bbb0649'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Metan con el, explica bien y es un 100 de persona, siempre tiene paciencia para explicar si uno no entiende algo, son cansadas las tareas pero una vez se sale de eso, se puede decir que pasó el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '87985d766ff6dde44e425f19f2a2d2638e578f7331786248d69e6088b28f79e5'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'e7bc40f97448fac8dacde6190898134de713f1c7631d18ec9fdaa2b1e9545b8f'::TEXT, ARRAY[1726]::BIGINT[]),
    (231::BIGINT, 'Explica muy bien, se interesa por el estudiante, hace que el curso no se sienta pesado, definitivamente no lo piensen, matriculen con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '1d8b33052f5c9ebbe81223baf66bd58b2867bad417471147288b5f8397c04535'::TEXT, ARRAY[1726]::BIGINT[]),
