    (231::BIGINT, 'Muy buen profesor'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '03dbc2d92d7bf65d7c0fa566da33a30b0d72789a40581fba359bc8baa8a03016'::TEXT, ARRAY[1726]::BIGINT[]),
    (231::BIGINT, 'Da muchos ejemplos en clase, se toma el tiempo para explicar si alguien no entiende. Muy buen profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '5e8edef0b1613715b999f914d2c8c0d5039772d71ab8e8c8ba66e005d4fc5987'::TEXT, ARRAY[1726]::BIGINT[]),
