    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-24T00:00:00+00:00'::TIMESTAMPTZ, '284dc8b7e9f3bddfd9acc9cb090baef0f7397d7be48b6d05969865e3c7fae6f8'::TEXT, ARRAY[1726]::BIGINT[]),
    (231::BIGINT, 'Excelente profesor! Ayuda un montón si usted no entiende algo. Es super paciente. Es muy divertido, lo cual hace la clase muy amena. Al final, es como un compa. De los mejores profes que he tenido. 1000% recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, '834dbd6a44c2294a103fd4e9fa86929dbe7baad6ba3e3938bb015f1bed637a8f'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Buen profe, un curso intensivo con demasiados contenidos pero si se logró aprovechar al máximos todas las sesiones'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, '667ebd618d3a93a9ba71c8e5477e360b6f80d6cc27a4c02f2c4664bb2b18a3d5'::TEXT, ARRAY[1468]::BIGINT[]),
    (231::BIGINT, 'Excelente profesor, el curso se hace bastante entretenido y se aprende bastante, demasiado pura vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '47c37e685a6bd1c9db9e1436c62b288e92be57b6d3b4a2f3bdfb84f7d14fb695'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'El profe siempre está dispuesto a ayudar y hace que el curso no sea tan difícil. 10/10'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'de1d300f75cf0c0e5b8d1a16e8b8f5c90897694b2e56fcdf17aa1047bb51792c'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'fcfff01e841fa7ab7a24f0ec9dd6b0fa2a14d82261b3e541d8be9e1d0577cb3f'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Explica muy bien, se toma el tiempo de volver a explicar si el estudiante no ha entendido. En consulta aclara muy bien las dudas. Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '79debbb56648bc72b74b3237f4cecf7af1c6a92fab90c8b385b89bce94fc3e52'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Un muy buen profesor, hace que la clase no sea tan dura a pesar de ser un curso un poco pesado. Explica bien, responde las dudas lo mejor y más pronto posible, tiene mucha paciencia'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'de611ab4d13026586211da63479d04fd9e00723777bcae75aa92a9c8888c99ff'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '5c3794555f8ca7f931a9c9533de13e036066d1fab32d0e5276c2f7c4e5e6cac8'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Muy buen profe. El curso es pesado pero cuando se llega a Autocad y Solidworks se aliviana y es tuanis. El profe en todo momento va a estar dispuesto a ayudarle, ya sea que le tenga que explicar diez veces'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, '1d3d75011aed8cf80c0c5915e0ddc266272a56c435dbcd0747ce2e5ce995b91d'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Un profesor ejemplar. El curso como tal es un poco pesado, más que nada al inicio ya que las tareas a mano toman mucho tiempo. Sin embargo, el profe siempre estuvo dispuesto a atendernos para despejar dudas o ayudarnos de cualquier manera que le fuera posible. Es muy amigable y comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f294737fe3d37174c82779ed53304f9a4f8e3242fee4a2b24125317512c9edcb'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente profe, se preocupa porque todos entiendan, muy buena gente, paciente, explica muy bien en consulta, de los mejores profes que he tenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '886741dba18c1012a3b7edf8f91ed250af6a97bbfbca412065d2b2168640ec82'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'El profe es una teja, explica bien y califica suave. No dude en matricular con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '00ba7ba66351ffa60fa2207aedbf3b89e1a02045908340eff05eb8a79abb4372'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Muy buen profesor y muy buena persona'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '64fd9c60dcbe247b720d3f8372cd83e1622e88c5013deb057bb1f5828ba046d0'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Recomendado 100% apesar de que el curso es un poco cansado el profe tiene una disposición de ayuda y de dejar todo claro, no lo piense para llevarlo con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'd9cc5bc1cdf5daacf9ccc829eab9907e0ff6a4c6de70babc2610ce26e5f484c7'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'En lo personal me costó mucho el curso al inicio, pero el siempre estuvo dispuesto a ayudar cuando observaba que uno se quedaba atrás, y se interesaba porque todo quedara claro, sin duda un 10 como persona y como profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '590175e674b014f367da15e2e14232b0ae370af1057a6d9e4515cd3ab56db903'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, '6b6bfded1807fe3dbab08aa38aa932c0769fd772394c99a616099e4930fb545d'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente profesor, siempre dispuesto a atender cualquier consulta y super buena gente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '138d97b61315cf35ebb8694da43db735a7fc9fe149b6cfa9f55980d36e65652d'::TEXT, ARRAY[1468]::BIGINT[]),
    (231::BIGINT, 'El Prof es muy buena gente, accesible para preguntarle cualquier cosa Las clases son entretenidas y se nota el conocimiento'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f381105594b1d920726c18baa42d3ab7bb6fc558f07568d66c560677280a245c'::TEXT, ARRAY[1468]::BIGINT[]),
    (231::BIGINT, 'Excelente profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '21b1eaca22c0cc87a1f1fcd047bd56221fb7964e485dc1890d188faf27be5132'::TEXT, ARRAY[1468]::BIGINT[]),
    (231::BIGINT, 'Súper buena nota y amable, muy comprensivo con las tareas y asistencia, se pasa fácil fácil y explica demasiado bien, de los mejores profes del TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, '0b368d70837fcd244ba8a40ca9ed211c2a6b23fc5d50bcc7847ce68ec1780521'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'EL MEJOR PROFE DEL TEC. LA PERSONA MAS COMPRENSIVA QUE HE CONOCIDO. HABLELE CON LA VERDAD Y EL VA A COMPRENDER. Ademas de tuanis, el mae hace el curso llevadero y chiva. Solo ponga de su parte y todo va a salir bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-09T00:00:00+00:00'::TIMESTAMPTZ, '792e932582c1c5e3a4c70a579eb4e38808bbe3cd6fccb9d0ce6e926b4f2cd3a0'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente profesor y excelente persona. Logra que tantas horas de clase sean llevaderas y divertidas, además se preocupa mucho porque los estudiantes entiendan.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1fbc64aa6ebbd180e648b29839a02d043dc3eeafd1ce5889c7cfc6cbc04ea5bd'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '2de3014104e1690708aa9a22a359686606c6e8c1b071767483567a013bf84b4e'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es el mejor profe que hay. Siempre intenta que todos entiendan y si alguien no entiende entonces le ayuda las veces que sea necesario. Es muy comprensivo y hace que las clases sean divertidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, '884450b4d3060446c2f7f2b5f598d6a30bd1cdb72821a53e1700ebd1fa1414a1'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Un profe comprensivo. De los pocos que hay en el TEC. Faltan más como él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'ca287810db931114fd6d8c5aca7dae7714afceec2210b973c318a73439f2d80c'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente profesor, el mejor de dibujo!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '03db5b4c94f2a733c221a609872f493151057a5d4df04ee415566044a40b190b'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '004ff950df5b5d5d823723f7f61fb47f8c7a45e327369d500dfc7c200cbb0f2a'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Muy buen Profe, ayuda un montón y se esfuerza por que uno entienda la materia, no importa que tenga que explicar 10 veces.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a84c8295976ba8708dae45290d43f3084ed7ae62c8f351aae6c742caee07c400'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es un amor de profe. La mejor decisión que puede tomar es matricular con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, '584c67635f95ea599069e5c65f5d0d0a787fc5cc2a94836dbdfcfffd7d0afff7'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Recibí este semestre y la verdad muy buen profesor, muy tuanis, ayuda mucho, explica bien(las veces que sea) y es calidad, super recomendado..'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a57e630357bd3621270013446520929b84eaf5cffa49e42c511f6866f0bae339'::TEXT, ARRAY[610]::BIGINT[]),
