    (231::BIGINT, 'Excelente profesor, si tiene que quedarse con usted 30 minutos para que entienda se queda, clase bastante llevadera a pesar de lo tedioso que puede llegar a ser el curso, y una excelente persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '5c3b2905775e737bf5df9efc382ac804668a00490ca760c036a0d88524f9a15f'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd88daccd9bae88a8601755bb998b3c8a371171a26b12ea1dcc979cd01991a09e'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es un excelente profesor, super atento en las dos partes del curso y tienen muchísima paciencia para explicar los temas complicados. Tiende a llegar tarde'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1a14ed3cc5d3a2a0822120c6cc1f5b3318d8a6edb3c5c0288ae15a2d4cf83837'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Si tiene que ir hasta su silla a explicarle las cosas lo hace con la mejor disposición, es muy condescendiente a la hora de calificar y hace las clases muy agradables, recomendado!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '358e49b17e6f749f1472407e6a087527a89fa746498cf796cf6d59882740e068'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'f25ef907196144642e40ca5dc1596cfc592beb4acd5eddee31397c41302f377d'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Super genial. En la parte a mano explica lo necesario y tiene buen material de ayuda. En solid y cad explica bien. A veces llega tarde'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '9b29035483172c62f97ffa45e38dd3b687f896ea190a38499057df1a5ec04d5c'::TEXT, ARRAY[610]::BIGINT[]),
