    (231::BIGINT, 'Excelente profe, no hay nada mejor en mante, la verdad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-06T00:00:00+00:00'::TIMESTAMPTZ, 'dc053f3577675c634ab34c686d73606127dc7d2db961b61148026c9dfb831980'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente persona y profesor, explica la materia con mucha claridad y de forma sencilla, si se tiene alguna duda explica las veces que sea necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-02T00:00:00+00:00'::TIMESTAMPTZ, '75e088980a64b930288d428e37672eb93c241ed4689b0d32c5da0b142afe6a6d'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente profe muy llevaderas las clases . Da buen apoyo en las dudas. Es claro, preciso y entendible cuando explica.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '7b8a4d3fe641e564076fc83a588b69e9eadf1513e1989f94937f39fa2c2e7677'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es un excelente profe, siempre busca aclarar todas las dudas, es comprensivo y explica muy bien. Toma en cuenta el esfuerzo de uno durante el curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'dd1723ed53ac6e2664b5e35c6c4277e3982eb4d79b0980f773b40cc7846f0cc7'::TEXT, ARRAY[610]::BIGINT[]),
