    (231::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '0dbe15c25716d26b2214d8884c6f420dc6121d57ac29516671b6610260e1597d'::TEXT, ARRAY[610, 1428]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '784bc67608bec7b8ea2dc3a61b09f56e9b8cb9c6ca2987d1fe0a47aa0400a42e'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es un profesor muy pura vida, califica suave y si uno no entendió algo entonces se lo explica cuantas veces sea necesaria hasta que uno entienda. Volvería a llevar un curso con él de fijo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '653c44d37bbe928be9c1b8a636e4725be6682a51773e4555974ae379fc40bcab'::TEXT, ARRAY[610]::BIGINT[]),
