    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '5c4636450b7549eaf8253f4b6a6c3a1f16f3de51893d4ed33c984f67bdb34a07'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'd55cc007a04b001d1ed1717f0c94496512f900218cf7233ee471fc3f5119a740'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente profe.. clases muy entretenidas.. se preocupa mucho porque el estudiante aprenda.. muy dedicado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd04027575082b2d8c8a479ed20cd991d460406f94bd9698120ab853c145552b7'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'El profe es muy buena gente y se aprende bastante con él, además que explica las veces que sean necesarias'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '75b5a2517eddc6fb03b9768ba1afd4c8f1afdaf5d304e8ed8608bfee8d7f3096'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '2a5c2d012fb08326aa074b8879fff557b26a69290cb5a6967dd3c166f30dd503'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Excelente persona, se ve que le interesa que el estudiante aprenda y explica las veces que uno lo necesite. Excelente para este curso. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f4fa278ccaa18ff8fbf4eb7ba04b979a73aeabe86984dcac8669abe4b3615756'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'A pesar de que el curso es pasado y un poco tedioso al principio por la parte manual puedo decir que es el mejor Profe que he tenido en el tec, el compromiso que tiene con los alumnos es increíble podría llevar cualquier otro curso con estén profe es súper amable, claro y entiende al estudiante.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, '4f93bddbab567f50e0c145543a238aba1b152fff223b3c9689671bae23e44d88'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'cf42018dd5ff648e716d5f714a37a4f2cf0ae46a23f562fcd7ba668a145c8146'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Creo que en lo único que debe mejorar es en la ultima fase del curso, de no leer tanta diapositiva, no explicar cosas teóricas y hacer mas ejemplos prácticos en el software. Pero vale la pena, ojala siga así!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '70a126aff7e98dd90aa9049473eb20274164031dc71391abb52428f7792ba885'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '53c0e3442a05c7450d568e86ea50f1dc2b80793da9bbab571fd93dbcbfe85fec'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Una excelente persona y eso se refleja en la manera de dar clases, siempre buscando lo mejor para uno como estudiante con tal de que uno pueda salir adelante. Recomendado full!'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '46155e5e722721ba208b4d3a2d1f0e6e2f339c2485948effbafda57770182698'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'El cabrón es nuevo y enseña mejor que cualquiera, ademas es muy humano y ayuda bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '07c1407bbb3ccb36be0c042dcc3a24c71c2e8f4ba417617c5e61fdb6dcdc3624'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es un buen profe y ayuda mucho con las dudas'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '1f2068ffa04f7cf5d1e316c4eefc93098b0270d2f6fb03d5bb50e51a7b4f64a0'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Es un excelente profesor, explica las veces necesarias para entender y te apoya en todo!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '7d6ad9913d3b6e2a25b753bb6eecb0c00d097a29c60a5882f0c778cf1bef19c7'::TEXT, ARRAY[610]::BIGINT[]),
    (231::BIGINT, 'Creo que es nuevo pero es muy buen profe, se preocupa mucho por el aprendizaje del estudiante. Metalo sin miedo, de los mejores profes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '679ff532aecd174a56d831fd7d6f83df557339f26cb356ec2bbd93b5e4031592'::TEXT, ARRAY[610]::BIGINT[])
